import AppKit
import Carbon.HIToolbox

/// Reading items off the pasteboard and writing them back.
enum Pasteboard {
    /// Types that password managers and similar apps set to ask clipboard tools not to record them.
    /// See http://nspasteboard.org
    static let privateTypes = Set([
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ].map { NSPasteboard.PasteboardType($0) })

    struct Capture {
        var item: Item
        var rtf: Data?
        var png: Data?
    }

    static func capture(_ pb: NSPasteboard, sourceApp: String?) -> Capture? {
        let types = Set(pb.types ?? [])
        guard types.isDisjoint(with: privateTypes) else { return nil }

        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map(\.path).joined(separator: "\n")
            return Capture(item: Item(kind: .files, text: paths, hash: "f:" + paths, sourceApp: sourceApp))
        }

        if let text = pb.string(forType: .string), !text.isEmpty {
            let rtf = pb.data(forType: .rtf)
            let item = Item(kind: .text, text: text, hasRTF: rtf != nil,
                            hash: Item.hash(Data(("t:" + text).utf8)), sourceApp: sourceApp)
            return Capture(item: item, rtf: rtf)
        }

        let png = pb.data(forType: .png)
            ?? pb.data(forType: .tiff).flatMap { NSBitmapImageRep(data: $0)?.representation(using: .png, properties: [:]) }
        if let png, let rep = NSBitmapImageRep(data: png) {
            let item = Item(kind: .image, text: "", imageSize: CGSize(width: rep.pixelsWide, height: rep.pixelsHigh),
                            hash: Item.hash(png), sourceApp: sourceApp)
            return Capture(item: item, png: png)
        }
        return nil
    }

    static func write(_ item: Item, store: Store, plainText: Bool, to pb: NSPasteboard = .general) {
        pb.clearContents()
        switch item.kind {
        case .text:
            pb.setString(item.text, forType: .string)
            if item.hasRTF, !plainText, let rtf = try? Data(contentsOf: store.payloadURL(item, "rtf")) {
                pb.setData(rtf, forType: .rtf)
            }
        case .image:
            if let image = NSImage(contentsOf: store.payloadURL(item, "png")) {
                pb.writeObjects([image])
            }
        case .files:
            let urls = item.text.split(separator: "\n").map { URL(fileURLWithPath: String($0)) as NSURL }
            pb.writeObjects(urls)
        }
    }

    /// Presses ⌘V in whatever app is frontmost. Needs the Accessibility permission.
    static func sendPaste() {
        let source = CGEventSource(stateID: .combinedSessionState)
        for keyDown in [true, false] {
            let event = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: keyDown)
            event?.flags = .maskCommand
            event?.post(tap: .cghidEventTap)
        }
    }
}

/// Polls the pasteboard. macOS has no change notification, so every clipboard tool does this.
final class Monitor {
    private let store: Store
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    init(store: Store) { self.store = store }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
    }

    /// Call after writing to the pasteboard ourselves, so the write isn't recorded as a new copy.
    func ignoreCurrent() {
        lastChange = NSPasteboard.general.changeCount
    }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount

        let app = NSWorkspace.shared.frontmostApplication
        if let id = app?.bundleIdentifier, Settings.ignoredApps[id] != nil { return }
        if let capture = Pasteboard.capture(pb, sourceApp: app?.localizedName) {
            store.add(capture.item, rtf: capture.rtf, png: capture.png)
        }
    }
}

enum Settings {
    static var maxItems: Int {
        get { UserDefaults.standard.object(forKey: "maxItems") as? Int ?? 500 }
        set { UserDefaults.standard.set(newValue, forKey: "maxItems") }
    }

    /// Bundle ID → app name.
    static var ignoredApps: [String: String] {
        get { UserDefaults.standard.dictionary(forKey: "ignoredApps") as? [String: String] ?? [:] }
        set { UserDefaults.standard.set(newValue, forKey: "ignoredApps") }
    }
}
